import re

def semver_compare(a, b):
    pattern = r'^(0|[1-9]\d*)\.(0|[1-9]\d*)\.(0|[1-9]\d*)(?:-([0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*))?(?:\+([0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*))?$'

    ma = re.match(pattern, a)
    mb = re.match(pattern, b)

    if not ma or not mb:
        raise ValueError(f"Invalid version string")

    a_major, a_minor, a_patch = int(ma.group(1)), int(ma.group(2)), int(ma.group(3))
    b_major, b_minor, b_patch = int(mb.group(1)), int(mb.group(2)), int(mb.group(3))

    a_pre = ma.group(4)
    b_pre = mb.group(4)

    if (a_major, a_minor, a_patch) != (b_major, b_minor, b_patch):
        return -1 if (a_major, a_minor, a_patch) < (b_major, b_minor, b_patch) else 1

    if a_pre is None and b_pre is None:
        return 0
    if a_pre is None:
        return 1
    if b_pre is None:
        return -1

    a_ids = a_pre.split('.')
    b_ids = b_pre.split('.')

    for ai, bi in zip(a_ids, b_ids):
        ai_is_digit = ai.isdigit()
        bi_is_digit = bi.isdigit()

        if ai_is_digit and bi_is_digit:
            ai_num = int(ai)
            bi_num = int(bi)
            if ai_num < bi_num:
                return -1
            elif ai_num > bi_num:
                return 1
        elif ai_is_digit:
            return -1
        elif bi_is_digit:
            return 1
        else:
            if ai < bi:
                return -1
            elif ai > bi:
                return 1

    if len(a_ids) < len(b_ids):
        return -1
    elif len(a_ids) > len(b_ids):
        return 1
    else:
        return 0

# Exact examples from the task
tests = [
   (( "1.0.0", "2.0.0"), -1),
   (( "2.1.1", "2.1.0"), 1),
   (( "1.0.0-alpha", "1.0.0"), -1),
   (( "1.0.0-alpha.1", "1.0.0-alpha.beta"), -1),
   (( "1.0.0+build.5", "1.0.0"), 0),
]

all_pass = True
for (a, b), expected in tests:
    result = semver_compare(a, b)
    if result != expected:
        print(f"FAIL: semver_compare({a!r}, {b!r}) = {result}, expected {expected}")
        all_pass = False
    else:
        print(f"PASS: semver_compare({a!r}, {b!r}) = {result}")

# Invalid version tests
invalid_tests = [("1.0", "1.0.0"), ("01.0.0", "1.0.0")]
for a, b in invalid_tests:
    try:
        semver_compare(a, b)
        print(f"FAIL: semver_compare({a!r}, {b!r}) should raise ValueError")
        all_pass = False
    except ValueError:
        print(f"PASS: semver_compare({a!r}, {b!r}) raises ValueError")

if all_pass:
    print("ALL TESTS PASSED")
else:
    print("NOT ALL TESTS PASSED")

